Tautology     & \textcolor{darkgreen}{\checkmark} Yes & \textcolor{darkgreen}{\checkmark} Yes \\
\hline
Contingency   & \textcolor{red}{$\times$} No           & \textcolor{darkgreen}{\checkmark} Yes \\
\hline
Contradiction & \textcolor{red}{$\times$} No           & \textcolor{red}{$\times$} No \\
\hline
\end{tabular}
\end{center}

