\]

\vspace{0.5cm}

Prove that $\neg p \leftrightarrow q \;\equiv\; p \leftrightarrow \neg q$
using logical equivalences.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
Recall: $A \leftrightarrow B \equiv (A \rightarrow B) \land (B \rightarrow A)$
and $A \rightarrow B \equiv \neg A \lor B$.

\vspace{0.3cm}
\textbf{Left-hand side:}
\begin{align*}
    \neg p \leftrightarrow q
    &\equiv (\neg p \rightarrow q) \land (q \rightarrow \neg p) \\
    &\equiv (p \lor q) \land (\neg q \lor \neg p) \\
    &\equiv (p \lor q) \land \neg(q \land p)
        &&\text{De Morgan on } \neg q \lor \neg p \\
    &\equiv (p \lor q) \land \neg(p \land q)
        &&\text{Commutative Law}
\end{align*}

\textbf{Right-hand side:}
\begin{align*}
    p \leftrightarrow \neg q
    &\equiv (p \rightarrow \neg q) \land (\neg q \rightarrow p) \\
    &\equiv (\neg p \lor \neg q) \land (q \lor p) \\
    &\equiv \neg(p \land q) \land (p \lor q)
        &&\text{De Morgan; Commutative} \\
    &\equiv (p \lor q) \land \neg(p \land q)
        &&\text{Commutative Law}
\end{align*}

\vspace{0.2cm}
Both sides simplify to $(p \lor q) \land \neg(p \land q)$.

\textcolor{darkgreen}{\textbf{Conclusion:}}
\[
    \boxed{\neg p \leftrightarrow q \;\equiv\; p \leftrightarrow \neg q} \quad \textcolor{darkgreen}{\checkmark}
\]

\vspace{0.5cm}

Show that $\neg(p \oplus q)$ and $p \leftrightarrow q$ are logically equivalent.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Method: Truth Table.}

Recall: $p \oplus q$ is true when exactly one of $p$, $q$ is true.

\vspace{0.3cm}
\begin{center}
\begin{tabular}{|c|c|c|c|c|}
\hline
\rowcolor{primaryblue!20}
$p$ & $q$ & $p \oplus q$ & $\neg(p \oplus q)$ & $p \leftrightarrow q$ \\
\hline
T & T & F & T & T \\
\hline
T & F & T & F & F \\
\hline
F & T & T & F & F \\
\hline
F & F & F & T & T \\
\hline
\end{tabular}
\end{center}

\vspace{0.3cm}
The columns for $\neg(p \oplus q)$ and $p \leftrightarrow q$ are identical: T, F, F, T.

\textcolor{darkgreen}{\textbf{Conclusion:}}
\[
    \boxed{\neg(p \oplus q) \;\equiv\; p \leftrightarrow q}
\]

\textbf{Intuition:} $p \oplus q$ is true when $p$ and $q$ \textit{differ}.
Negating that gives truth when they are the \textit{same} --- which is exactly
what the biconditional means.

\vspace{0.5cm}

Find the dual of $(p \lor \mathbf{F}) \land (q \lor \mathbf{T})$.

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{Solution:}}

\vspace{0.3cm}
\textbf{Definition of Dual:} To find the dual of a compound proposition,
replace every $\lor$ with $\land$, every $\land$ with $\lor$,
every $\mathbf{T}$ with $\mathbf{F}$, and every $\mathbf{F}$ with $\mathbf{T}$.
\textit{Do not change the propositional variables or negations.}

\vspace{0.3cm}
\textbf{Original:} $(p \lor \mathbf{F}) \land (q \lor \mathbf{T})$

\vspace{0.3cm}
\textbf{Step-by-step substitution:}
\begin{itemize}[leftmargin=1.5em]
    \item Outer $\land \;\longrightarrow\; \lor$
    \item First $\lor \;\longrightarrow\; \land$
    \item $\mathbf{F} \;\longrightarrow\; \mathbf{T}$
    \item Second $\lor \;\longrightarrow\; \land$
    \item $\mathbf{T} \;\longrightarrow\; \mathbf{F}$
\end{itemize}

\vspace{0.3cm}
\textbf{Dual:}
\[
    \boxed{(p \land \mathbf{T}) \lor (q \land \mathbf{F})}
\]

\vspace{0.3cm}
\textbf{Simplification of the dual using laws:}
\begin{align*}
    (p \land \mathbf{T}) \lor (q \land \mathbf{F})
    &\equiv p \lor \mathbf{F} &&\text{Identity Law; Domination Law}\\
    &\equiv p &&\text{Identity Law}
\end{align*}

\textbf{Simplification of the original for comparison:}
\begin{align*}
    (p \lor \mathbf{F}) \land (q \lor \mathbf{T})
    &\equiv p \land \mathbf{T} &&\text{Identity Law; Domination Law}\\
    &\equiv p &&\text{Identity Law}
\end{align*}

\textcolor{accentorange}{\textbf{Note:}} Both the original and its dual simplify
to $p$ in this case, but this is a coincidence --- duals are generally not equivalent
to the original.

\vspace{0.5cm}




