\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Quick Reference:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Concept} & \textbf{Symbol} & \textbf{True when} & \textbf{To disprove} \\
\hline
Universal & $\forall x\, P(x)$ & All elements satisfy $P$ & One counterexample \\
\hline
Existential & $\exists x\, P(x)$ & At least one satisfies $P$ & Show all fail \\
\hline
Unique & $\exists!\, x\, P(x)$ & Exactly one satisfies $P$ & Show 0 or 2+ satisfy \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Negation Rules (De Morgan for Quantifiers):}}
\[
    \neg\,\forall x\, P(x) \equiv \exists x\, \neg P(x)
    \qquad\qquad
    \neg\,\exists x\, P(x) \equiv \forall x\, \neg P(x)
\]

\vspace{0.3cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Translation Strategy:}}
\begin{enumerate}[leftmargin=2em]
    \item Identify all variables and assign predicate names.
    \item Look for keywords: ``all/every/each'' $\Rightarrow$ $\forall$;
          ``some/there exists/at least one'' $\Rightarrow$ $\exists$.
    \item ``All $A$ are $B$'' $\Rightarrow$ $\forall x\,(A(x) \rightarrow B(x))$.
    \item ``Some $A$ is $B$'' $\Rightarrow$ $\exists x\,(A(x) \land B(x))$.
    \item Note: use $\rightarrow$ with $\forall$; use $\land$ with $\exists$.
\end{enumerate}

