\vspace{0.5cm}

\textcolor{primaryblue}{\textbf{\faLightbulb\ Section 1.6 Summary --- Proof Techniques}}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ When to Use Which Technique:}}

\vspace{0.2cm}
\begin{center}
\begin{tabular}{|l|l|l|}
\hline
\rowcolor{primaryblue!20}
\textbf{Technique} & \textbf{When to use} & \textbf{Key move} \\
\hline
Direct Proof & $p$ gives useful info & Assume $p$, derive $q$ \\
\hline
Contraposition & $\neg q$ is easier to use & Assume $\neg q$, derive $\neg p$ \\
\hline
Contradiction & Proving irrationality, infinity & Assume $\neg p$, derive $\mathbf{F}$ \\
\hline
Induction & All $n \in \mathbb{Z}^+$ & Base + inductive step \\
\hline
Strong Induction & Need earlier cases & Assume $P(1),\ldots,P(k)$ \\
\hline
\end{tabular}
\end{center}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Induction Checklist:}}
\begin{enumerate}[leftmargin=2em]
    \item State $P(n)$ clearly.
    \item Prove the base case explicitly.
    \item Write: ``Assume $P(k)$ is true for some $k \geq 1$.''
    \item Write: ``We will show $P(k+1)$ is true.''
    \item Start from the LHS of $P(k+1)$, use the inductive hypothesis, reach the RHS.
    \item Conclude: ``By induction, $P(n)$ holds for all $n \geq 1$.''
\end{enumerate}

\vspace{0.4cm}
\textcolor{primaryblue}{\textbf{\faCheckCircle\ Key Formulas Proved by Induction:}}
